/**
 * Small-bore tube, hose, electrical-core and optical-fibre unit design checks for umbilicals.
 *
 * Notes that are not calculations:
 *  - Autofrettage (over-pressurising a thick tube so the bore yields and is left in residual compression) raises
 *    the elastic pressure range but not the burst pressure; it is not modelled. The elastic limit and fully
 *    plastic pressures returned by {@link thickWallLimitPressures} bound the autofrettage pressure.
 *  - Hydrogen darkening: hydrogen generated by corrosion of zinc/steel or by degradation of polymers diffuses
 *    into silica fibres and raises attenuation (notably near 1240 and 1383 nm). It is controlled by hermetic
 *    (welded steel) fibre tubes, hydrogen-scavenging gel and carbon-coated fibre, not by a mechanical check.
 */

function pos(v, name) {
  if (!(typeof v === 'number' && Number.isFinite(v) && v > 0)) throw new RangeError(`${name} must be a positive finite number`);
  return v;
}
function fin(v, name) {
  if (!(typeof v === 'number' && Number.isFinite(v))) throw new RangeError(`${name} must be a finite number`);
  return v;
}
function nonneg(v, name) {
  if (!(typeof v === 'number' && Number.isFinite(v) && v >= 0)) throw new RangeError(`${name} must be a non-negative finite number`);
  return v;
}
function radii(ri, ro) {
  pos(ri, 'ri'); pos(ro, 'ro');
  if (!(ro > ri)) throw new RangeError('ro must exceed ri');
}

/**
 * Von Mises equivalent stress from three normal stresses and one shear stress.
 * @param {object} o
 * @param {number} o.s1 Pa
 * @param {number} o.s2 Pa
 * @param {number} o.s3 Pa
 * @param {number} [o.tau=0] Pa
 * @returns {{vonMises:number}} Pa
 */
export function vonMises({ s1, s2, s3, tau = 0 }) {
  fin(s1, 's1'); fin(s2, 's2'); fin(s3, 's3'); fin(tau, 'tau');
  return { vonMises: Math.sqrt(0.5 * ((s1 - s2) ** 2 + (s2 - s3) ** 2 + (s3 - s1) ** 2) + 3 * tau * tau) };
}

/**
 * Lame thick-wall cylinder stresses at radius r:
 *     sigma_theta = A + B/r^2,  sigma_r = A - B/r^2,
 *     A = (pi ri^2 - po ro^2)/(ro^2 - ri^2),  B = (pi - po) ri^2 ro^2/(ro^2 - ri^2).
 * Axial stress: closed ends sigma_z = A (end-cap force over the wall area); open ends 0; an additional wall force
 * `axialForce` is spread over the wall area.
 * Reference: Lame (1852); Timoshenko & Goodier, Theory of Elasticity, §28.
 * Validity: linear elastic, axisymmetric, away from end effects.
 * @param {object} o
 * @param {number} o.pInt internal pressure, Pa
 * @param {number} [o.pExt=0] external pressure, Pa
 * @param {number} o.ri inner radius, m
 * @param {number} o.ro outer radius, m
 * @param {number} [o.r] radius of evaluation, m (default ri)
 * @param {'closed'|'open'} [o.ends='closed']
 * @param {number} [o.axialForce=0] additional true wall force, N
 * @returns {{radial:number, hoop:number, axial:number, vonMises:number}} Pa
 */
export function lameStresses({ pInt, pExt = 0, ri, ro, r, ends = 'closed', axialForce = 0 }) {
  fin(pInt, 'pInt'); fin(pExt, 'pExt'); radii(ri, ro); fin(axialForce, 'axialForce');
  const rr = r === undefined ? ri : r;
  if (!(rr >= ri * (1 - 1e-12) && rr <= ro * (1 + 1e-12))) throw new RangeError('r must lie between ri and ro');
  if (ends !== 'closed' && ends !== 'open') throw new RangeError("ends must be 'closed' or 'open'");
  const d = ro * ro - ri * ri;
  const A = (pInt * ri * ri - pExt * ro * ro) / d, B = (pInt - pExt) * ri * ri * ro * ro / d;
  const hoop = A + B / (rr * rr), radial = A - B / (rr * rr);
  const axial = (ends === 'closed' ? A : 0) + axialForce / (Math.PI * d);
  return { radial, hoop, axial, vonMises: vonMises({ s1: radial, s2: hoop, s3: axial }).vonMises };
}

/**
 * Thin-wall (membrane) stresses of a pressurised tube: hoop = (pi - po) Dm/(2 t) with the mean diameter
 * Dm = D - t (or Barlow's outside-diameter form (pi - po) D/(2 t) when `barlow` is set); closed-end axial = hoop/2.
 * Reference: membrane theory of shells; Barlow (1836).
 * Validity: D/t > ~20 for 5 % agreement with Lame at the bore.
 * @param {object} o
 * @param {number} o.pInt Pa
 * @param {number} [o.pExt=0] Pa
 * @param {number} o.D outside diameter, m
 * @param {number} o.t wall thickness, m
 * @param {boolean} [o.barlow=false] use D instead of D - t
 * @returns {{hoop:number, axial:number}} Pa
 */
export function thinWallStresses({ pInt, pExt = 0, D, t, barlow = false }) {
  fin(pInt, 'pInt'); fin(pExt, 'pExt'); pos(D, 'D'); pos(t, 't');
  if (!(t < D / 2)) throw new RangeError('t must be smaller than D/2');
  const hoop = (pInt - pExt) * (barlow ? D : D - t) / (2 * t);
  return { hoop, axial: hoop / 2 };
}

/**
 * Elastic-limit and fully plastic pressures of a closed-ended thick tube (von Mises, perfectly plastic):
 *     p_yield   = sigma_y (ro^2 - ri^2) / (sqrt(3) ro^2)     (first yield at the bore, Lame + von Mises)
 *     p_plastic = (2/sqrt(3)) sigma_y ln(ro/ri)              (wall fully plastic; with sigma_u in place of sigma_y
 *                                                             an estimate of ductile burst)
 * Reference: Hill, The Mathematical Theory of Plasticity, Ch. V; Nadai.
 * @param {object} o
 * @param {number} o.ri m
 * @param {number} o.ro m
 * @param {number} o.yieldStress Pa
 * @param {number} [o.uts] Pa
 * @returns {{pYield:number, pPlastic:number, pBurstEstimate:number|null}} Pa (net internal overpressure)
 */
export function thickWallLimitPressures({ ri, ro, yieldStress, uts }) {
  radii(ri, ro); pos(yieldStress, 'yieldStress');
  const k = 2 / Math.sqrt(3) * Math.log(ro / ri);
  return {
    pYield: yieldStress * (ro * ro - ri * ri) / (Math.sqrt(3) * ro * ro),
    pPlastic: k * yieldStress,
    pBurstEstimate: uts === undefined ? null : k * pos(uts, 'uts'),
  };
}

/**
 * Pressure design of a straight tube to ASME B31.3 §304.1.2 Eq. (3a):
 *     t = P D / (2 (S E W + P Y))   <=>   P = 2 S E W t / (D - 2 Y t)
 * S allowable stress, E quality factor, W weld-joint strength reduction factor, Y coefficient of Table 304.1.1
 * (0.4 for ferritic and austenitic steels and ductile metals at <= 482 degC when t < D/6). For t >= D/6 the code
 * requires special consideration; Y = (d + 2c)/(D + d + 2c) is used here with corrosion allowance c.
 * @param {object} o
 * @param {number} o.D outside diameter, m
 * @param {number} o.S allowable stress, Pa
 * @param {number} [o.t] pressure design thickness, m (give t to get P)
 * @param {number} [o.P] internal design gauge pressure, Pa (give P to get t)
 * @param {number} [o.E=1] quality factor
 * @param {number} [o.W=1] weld-joint strength reduction factor
 * @param {number} [o.Y] coefficient (default per the rule above)
 * @param {number} [o.c=0] sum of mechanical and corrosion allowances, m
 * @returns {{P:number, t:number, Y:number, thickWall:boolean}} Pa, m (pressure design thickness, excluding c), -
 */
export function b313PressureDesign({ D, S, t, P, E = 1, W = 1, Y, c = 0 }) {
  pos(D, 'D'); pos(S, 'S'); pos(E, 'E'); pos(W, 'W'); nonneg(c, 'c');
  if ((t === undefined) === (P === undefined)) throw new RangeError('give exactly one of t or P');
  const yFor = (tt) => {
    if (Y !== undefined) return pos(Y, 'Y');
    if (tt < D / 6) return 0.4;
    const d = D - 2 * (tt + c);
    return (d + 2 * c) / (D + d + 2 * c);
  };
  if (t !== undefined) {
    pos(t, 't');
    if (!(t < D / 2)) throw new RangeError('t must be smaller than D/2');
    const y = yFor(t);
    return { P: 2 * S * E * W * t / (D - 2 * y * t), t, Y: y, thickWall: t >= D / 6 };
  }
  pos(P, 'P');
  let y = Y ?? 0.4, tt = P * D / (2 * (S * E * W + P * y));
  if (Y === undefined && tt >= D / 6) {
    for (let i = 0; i < 50; i++) { y = yFor(tt); tt = P * D / (2 * (S * E * W + P * y)); }
  }
  return { P, t: tt, Y: y, thickWall: tt >= D / 6 };
}

/**
 * Pressure containment (bursting) resistance in the DNV-ST-F101 §5.4.2 form:
 *     p_b = (2 t/(D - t)) f_cb (2/sqrt(3)),   f_cb = min(f_y, f_u/1.15).
 * Reference: DNV-ST-F101 (2021) Eq. (5.8)-(5.9). Partial safety factors are applied by the caller.
 * Validity: D/t >= ~10 (thin-to-moderately thick pipe); small-bore umbilical tubes with lower D/t should also be
 * checked with {@link thickWallLimitPressures}.
 * @param {object} o
 * @param {number} o.D outside diameter, m
 * @param {number} o.t wall thickness, m
 * @param {number} o.fy yield stress, Pa
 * @param {number} o.fu tensile strength, Pa
 * @returns {{pb:number, fcb:number, yieldLimit:number, burstLimit:number}} Pa
 */
export function dnvBurstPressure({ D, t, fy, fu }) {
  pos(D, 'D'); pos(t, 't'); pos(fy, 'fy'); pos(fu, 'fu');
  if (!(t < D / 2)) throw new RangeError('t must be smaller than D/2');
  const g = 2 * t / (D - t) * 2 / Math.sqrt(3);
  const fcb = Math.min(fy, fu / 1.15);
  return { pb: g * fcb, fcb, yieldLimit: g * fy, burstLimit: g * fu / 1.15 };
}

/**
 * Collapse pressure of a tube under external overpressure with initial ovality (same cubic as for pipelines):
 *     (pc - pel)(pc^2 - pp^2) = pc pel pp f0 D/t
 *     pel = 2 E (t/D)^3/(1 - nu^2),  pp = fy alphaFab 2 t/D,  f0 = (Dmax - Dmin)/D (not less than 0.005).
 * Reference: DNV-ST-F101 (2021) Eq. (5.10)-(5.13), after Haagsma & Schaap (1981). Solved by bisection on
 * (0, min(pel, pp)).
 * Validity: D/t between about 10 and 60 in the source; for thicker small-bore tubes the plastic term governs and
 * the result is conservative.
 * @param {object} o
 * @param {number} o.D outside diameter, m
 * @param {number} o.t wall thickness, m
 * @param {number} o.E Young's modulus, Pa
 * @param {number} o.fy yield stress, Pa
 * @param {number} [o.nu=0.3]
 * @param {number} [o.ovality=0.005] f0; the code minimum 0.005 is enforced unless enforceMinimum is false
 * @param {number} [o.alphaFab=1] fabrication factor (seamless 1.0, UO/TRB/ERW 0.93, UOE 0.85)
 * @param {boolean} [o.enforceMinimum=true]
 * @returns {{pc:number, pel:number, pp:number, f0:number}} Pa
 */
export function tubeCollapsePressure({ D, t, E, fy, nu = 0.3, ovality = 0.005, alphaFab = 1, enforceMinimum = true }) {
  pos(D, 'D'); pos(t, 't'); pos(E, 'E'); pos(fy, 'fy'); nonneg(ovality, 'ovality'); pos(alphaFab, 'alphaFab');
  if (!(t < D / 2)) throw new RangeError('t must be smaller than D/2');
  const f0 = enforceMinimum ? Math.max(ovality, 0.005) : ovality;
  const pel = 2 * E * (t / D) ** 3 / (1 - nu * nu), pp = fy * alphaFab * 2 * t / D;
  const g = (p) => (p - pel) * (p * p - pp * pp) - p * pel * pp * f0 * D / t;
  let lo = 0, hi = Math.min(pel, pp);
  if (f0 === 0) return { pc: hi, pel, pp, f0 };
  for (let i = 0; i < 200; i++) { const mid = 0.5 * (lo + hi); if (g(mid) > 0) lo = mid; else hi = mid; }
  return { pc: 0.5 * (lo + hi), pel, pp, f0 };
}

/**
 * Combined pressure + tension + bending utilisation of a tube: von Mises stress at the bore and at the outer
 * surface on the tensile and compressive bending fibres, from Lame stresses, wall force T/A and bending stress
 * E r kappa (or M r/I), divided by eta x yield.
 * Reference: von Mises criterion; allowable utilisation eta per the governing code (ISO 13628-5 / API 17E use
 * load-condition dependent utilisation factors - supply the value).
 * Validity: elastic; bending strain linear over the section.
 * @param {object} o
 * @param {number} o.D outside diameter, m
 * @param {number} o.t wall thickness, m
 * @param {number} [o.pInt=0] Pa
 * @param {number} [o.pExt=0] Pa
 * @param {number} [o.tension=0] true wall force in addition to the closed-end pressure force, N
 * @param {number} [o.curvature] 1/m (with E), or
 * @param {number} [o.moment] bending moment, N m
 * @param {number} [o.E] Young's modulus, Pa (needed with curvature)
 * @param {number} o.yieldStress Pa
 * @param {number} [o.eta=1] allowable utilisation factor
 * @param {'closed'|'open'} [o.ends='closed']
 * @returns {{vonMisesMax:number, utilisation:number, location:string, bendingStressOuter:number,
 *   axialMembrane:number, hoopBore:number}} Pa, -, text, Pa, Pa, Pa
 */
export function tubeCombinedUtilisation({ D, t, pInt = 0, pExt = 0, tension = 0, curvature, moment, E, yieldStress, eta = 1, ends = 'closed' }) {
  pos(D, 'D'); pos(t, 't'); pos(yieldStress, 'yieldStress'); pos(eta, 'eta');
  const ro = D / 2, ri = ro - t;
  radii(ri, ro);
  let sbOuter = 0;
  if (curvature !== undefined) sbOuter = pos(E, 'E') * ro * nonneg(curvature, 'curvature');
  else if (moment !== undefined) sbOuter = Math.abs(fin(moment, 'moment')) * ro / (Math.PI * (ro ** 4 - ri ** 4) / 4);
  let worst = -1, location = '';
  for (const [name, r] of [['bore', ri], ['outer surface', ro]]) {
    const s = lameStresses({ pInt, pExt, ri, ro, r, ends, axialForce: tension });
    for (const sign of [1, -1]) {
      const vm = vonMises({ s1: s.radial, s2: s.hoop, s3: s.axial + sign * sbOuter * r / ro }).vonMises;
      if (vm > worst) { worst = vm; location = `${name}, ${sign > 0 ? 'tension' : 'compression'} side`; }
    }
  }
  const bore = lameStresses({ pInt, pExt, ri, ro, r: ri, ends, axialForce: tension });
  return { vonMisesMax: worst, utilisation: worst / (eta * yieldStress), location, bendingStressOuter: sbOuter, axialMembrane: bore.axial, hoopBore: bore.hoop };
}

/**
 * Proof / hydrostatic test pressure and the resulting bore utilisation. Steel umbilical tubes are commonly
 * proof-tested at 1.5 x design working pressure (ISO 13628-5 / API 17E, as recalled); hose proof factors differ.
 * The factor is an argument: take it from the governing specification.
 * @param {object} o
 * @param {number} o.designPressure Pa
 * @param {number} [o.proofFactor=1.5]
 * @param {number} [o.ri] inner radius, m (for the stress check)
 * @param {number} [o.ro] outer radius, m
 * @param {number} [o.yieldStress] Pa
 * @returns {{testPressure:number, vonMisesBore:number|null, utilisation:number|null}} Pa, Pa, -
 */
export function proofTestPressure({ designPressure, proofFactor = 1.5, ri, ro, yieldStress }) {
  pos(designPressure, 'designPressure'); pos(proofFactor, 'proofFactor');
  const testPressure = proofFactor * designPressure;
  let vm = null, ut = null;
  if (ri !== undefined && ro !== undefined) {
    vm = lameStresses({ pInt: testPressure, ri, ro }).vonMises;
    if (yieldStress !== undefined) ut = vm / pos(yieldStress, 'yieldStress');
  }
  return { testPressure, vonMisesBore: vm, utilisation: ut };
}

/**
 * Wall thinning at the extrados (and thickening at the intrados) of a bent tube from plane-strain volume
 * constancy with the neutral axis at the tube centre-line: the extrados fibre is stretched by (R + r)/R, so
 *     t_extrados = t R/(R + r),   t_intrados = t R/(R - r),   r = D/2 (to the outer surface, conservative).
 * Reference: first-principles geometry (same form as the usual tube-bending thinning rule).
 * Validity: R > D; no mandrel/boost effects; ovalisation not included.
 * @param {object} o
 * @param {number} o.t nominal wall, m
 * @param {number} o.D outside diameter, m
 * @param {number} o.bendRadius centre-line bend radius R, m
 * @returns {{tExtrados:number, tIntrados:number, thinningFraction:number, bendingStrain:number}} m, m, -, -
 */
export function tubeBendThinning({ t, D, bendRadius }) {
  pos(t, 't'); pos(D, 'D'); pos(bendRadius, 'bendRadius');
  if (!(bendRadius > D / 2)) throw new RangeError('bendRadius must exceed D/2');
  const r = D / 2;
  const tExtrados = t * bendRadius / (bendRadius + r);
  return { tExtrados, tIntrados: t * bendRadius / (bendRadius - r), thinningFraction: 1 - tExtrados / t, bendingStrain: r / bendRadius };
}

/**
 * Thermoplastic hose ratings from supplier data: design working pressure = burst pressure / burstRatio, and the
 * volume taken up on pressurisation dV = ve L dp, with ve the volumetric expansion coefficient of the hose
 * (m^3 per metre per Pa, from the hose qualification tests - it is strongly pressure and construction dependent).
 * Reference: ISO 13628-5 / API 17E hose requirements (minimum burst-to-design ratio 4:1 as recalled - argument).
 * @param {object} o
 * @param {number} o.burstPressure Pa
 * @param {number} [o.burstRatio=4]
 * @param {number} [o.volumetricExpansion=0] ve, m^3/(m Pa)
 * @param {number} [o.length=0] m
 * @param {number} [o.pressureChange=0] Pa
 * @returns {{designPressure:number, expansionVolume:number}} Pa, m^3
 */
export function hoseRating({ burstPressure, burstRatio = 4, volumetricExpansion = 0, length = 0, pressureChange = 0 }) {
  pos(burstPressure, 'burstPressure'); pos(burstRatio, 'burstRatio'); nonneg(volumetricExpansion, 'volumetricExpansion');
  nonneg(length, 'length'); fin(pressureChange, 'pressureChange');
  return { designPressure: burstPressure / burstRatio, expansionVolume: volumetricExpansion * length * pressureChange };
}

/**
 * Insulation resistance of a coaxial cable core of length L: R = rho ln(D/d) / (2 pi L) (radial conduction
 * through the dielectric). Often quoted as an insulation-resistance constant in ohm km.
 * Reference: radial resistance of a cylindrical shell (e.g. IEC 60502 insulation-resistance constant Ki).
 * @param {object} o
 * @param {number} o.resistivity volume resistivity of the insulation, ohm m
 * @param {number} o.conductorDiameter d, m
 * @param {number} o.insulationDiameter D, m
 * @param {number} o.length L, m
 * @returns {{resistance:number, resistanceKm:number}} ohm; ohm km
 */
export function insulationResistance({ resistivity, conductorDiameter, insulationDiameter, length }) {
  pos(resistivity, 'resistivity'); pos(conductorDiameter, 'conductorDiameter'); pos(insulationDiameter, 'insulationDiameter'); pos(length, 'length');
  if (!(insulationDiameter > conductorDiameter)) throw new RangeError('insulationDiameter must exceed conductorDiameter');
  const perMetre = resistivity * Math.log(insulationDiameter / conductorDiameter) / (2 * Math.PI);
  return { resistance: perMetre / length, resistanceKm: perMetre / 1000 };
}

/**
 * Strain-free window of an optical fibre in a loose tube (geometric derivation).
 * The tube is stranded at pitch radius Rp with lay length p; the fibre can move radially by the clearance
 * a = (tube inner diameter - fibre or bundle diameter)/2 about the tube axis. With excess fibre length e0
 * relative to the tube axis the unstrained fibre length per lay is Lf = (1 + e0) sqrt(p^2 + (2 pi Rp)^2).
 * Under cable elongation the fibre migrates to the smallest available radius rMin = max(Rp - a, 0) before it is
 * strained; under contraction (thermal or compression) to rMax = Rp + a before it buckles against the wall:
 *     eps_tension     = sqrt(Lf^2 - (2 pi rMin)^2)/p - 1
 *     eps_contraction = 1 - sqrt(Lf^2 - (2 pi rMax)^2)/p
 * For a central (unstranded) tube Rp = 0 and eps_tension = e0. Radial contraction of the cable is neglected.
 * Fibre strain beyond the window is the cable strain minus the window, checked against a long-term allowable
 * expressed as a fraction of the proof-test strain.
 * Reference: geometry of the helix; fibre proof-test levels are typically 0.69 GPa (about 1 % strain) with
 * long-term allowable strains of order 0.2-0.33 of proof - both are arguments here.
 * @param {object} o
 * @param {number} o.layLength p, m
 * @param {number} [o.pitchRadius=0] Rp, m
 * @param {number} o.clearance a, m
 * @param {number} [o.efl=0] excess fibre length e0 (fraction, may be negative)
 * @param {number} [o.cableStrain] applied cable strain (positive tension), -
 * @param {number} [o.proofStrain=0.01] fibre proof-test strain, -
 * @param {number} [o.allowableFraction=0.2] allowable long-term fibre strain / proof strain
 * @returns {{tensileWindow:number, contractionWindow:number, fibreStrain:number|null, allowableStrain:number,
 *   utilisation:number|null}} all strains as fractions
 */
export function looseTubeStrainWindow({ layLength, pitchRadius = 0, clearance, efl = 0, cableStrain, proofStrain = 0.01, allowableFraction = 0.2 }) {
  pos(layLength, 'layLength'); nonneg(pitchRadius, 'pitchRadius'); nonneg(clearance, 'clearance'); fin(efl, 'efl');
  pos(proofStrain, 'proofStrain'); pos(allowableFraction, 'allowableFraction');
  const c = 2 * Math.PI, p = layLength;
  const Lf = (1 + efl) * Math.hypot(p, c * pitchRadius);
  const rMin = Math.max(pitchRadius - clearance, 0), rMax = pitchRadius + clearance;
  const inner = Lf * Lf - (c * rMin) ** 2, outer = Lf * Lf - (c * rMax) ** 2;
  if (inner <= 0) throw new RangeError('efl is too negative for this geometry');
  const tensileWindow = Math.sqrt(inner) / p - 1;
  // if even a fully collapsed lay cannot use up the wall clearance the contraction window is unlimited (1)
  const contractionWindow = outer > 0 ? 1 - Math.sqrt(outer) / p : 1;
  const allowableStrain = allowableFraction * proofStrain;
  let fibreStrain = null;
  if (cableStrain !== undefined) fibreStrain = Math.max(fin(cableStrain, 'cableStrain') - tensileWindow, 0);
  return { tensileWindow, contractionWindow, fibreStrain, allowableStrain, utilisation: fibreStrain === null ? null : fibreStrain / allowableStrain };
}
